TREES.constipation = {
id:'constipation',
nodes:{

// ========== 第一步：入口 ==========
start:{q:'大便是什么样的？或者属于哪类人群？',hint:'胡老说治便秘先看大便本身——干硬如羊屎=燥结（阳明）；不干但拉不出=气滞/虚（少阳/太阴）；先干后稀=脾虚（太阴）。六经皆可便秘，便秘≠上火！儿童/老人/孕妇有特殊考虑。',opts:[
  {text:'干硬像羊屎粒粒',icon:'🐑',next:'dry'},
  {text:'不干但就是拉不出来',icon:'😣',next:'notdry'},
  {text:'先干后稀（开头硬后面稀）',icon:'🔄',next:'lizhong'},
  {text:'儿童/老人/孕妇/感冒后等特殊情况',icon:'👨‍👩‍👧',next:'special'}
]},

// ========== 第二步：燥结型 ==========
dry:{q:'肚子胀痛吗？全身状况如何？',hint:'燥结型便秘——实质是"阳明腑实"。根据痞满燥实程度选承气汤类或润下麻子仁丸。',opts:[
  {text:'腹胀满硬痛拒按+可能发烧说胡话',icon:'🚫',next:'dachengqi'},
  {text:'腹胀满但不痛+嗳气打嗝',icon:'😐',next:'xiaochengqi'},
  {text:'大便干结+心烦+口渴+舌红苔黄',icon:'😤',next:'tiaoweichengqi'},
  {text:'老人/产妇/病后+羊屎便+小便多+无明显腹胀痛',icon:'👵',next:'maziren'}
]},

// ========== 第三步：非燥结型 ==========
notdry:{q:'伴随什么感觉？',hint:'大便不干但排不出=不是燥结！是气滞/虚寒/血虚/表郁。不能用承气汤攻下——越攻越虚。',opts:[
  {text:'腹胀+打嗝放屁多+情绪波动加重',icon:'💨',next:'sinisan'},
  {text:'口苦+胸胁不舒服+没胃口',icon:'🤪',next:'xiaochaihu'},
  {text:'怕冷+手脚冰凉+腹痛',icon:'🥶',next:'dahuangfuzi'},
  {text:'面色萎黄+月经量少+皮肤干燥',icon:'😰',next:'danggui'},
  {text:'老人排便无力+怕冷+腰膝酸软',icon:'🧓',next:'shenqi'},
  {text:'全身极度怕冷+疲倦嗜睡+完全不排便',icon:'❄️',next:'sini'},
  {text:'感冒后便秘+怕冷无汗+浑身酸痛',icon:'🤧',next:'mahuang'}
]},

// ========== 第四步：特殊人群 ==========
special:{q:'哪类特殊情况？',hint:'儿童/老人/孕妇/外感便秘各有专方。儿童忌猛攻，老人看寒热，孕妇重养血。',opts:[
  {text:'儿童+不爱吃饭+肚子胀+口臭+大便酸臭',icon:'🍔',next:'baohe'},
  {text:'儿童+怕冷+肚子隐痛喜揉+不爱吃饭',icon:'🧒',next:'xiaojianzhong'},
  {text:'老人+排便无力+怕冷+腰膝酸软',icon:'🧓',next:'shenqi'},
  {text:'老人/产妇+羊屎便+小便多+无明显胀痛',icon:'👵',next:'maziren'},
  {text:'孕妇+面色萎黄+大便干涩难出',icon:'🤰',next:'danggui'},
  {text:'感冒后便秘+怕冷无汗+浑身酸痛',icon:'🤧',next:'mahuang'}
]},

// ===================================================================
// 阳明实热四方
// ===================================================================

dachengqi:{syndrome:'阳明病 · 大承气汤（痞满燥实重症）',symptoms:'大便干硬多日不通、腹胀满硬痛拒按、潮热谵语、舌焦黄起刺、脉沉实有力',original:'《伤寒论》208条："阳明病……手足濈然汗出者，此大便已硬也，大承气汤主之。"',formula:'大黄12g（后下） 厚朴15g 枳实12g 芒硝9g（冲服）',method:'先煮厚朴枳实，后下大黄，去渣后溶入芒硝。分两次温服，得下即停。',otc:'无成药——必须辨证使用',warning:'痞满燥实四证不全者不可用。中病即止，不可过服！',hulao:'胡老说：痞（腹满）满（腹胀）燥（干结）实（拒按）四者俱全才是大承气汤证。缺一不可。这是攻下的最强方，中病即止！',combo:'得下即停，不可久服。忌油腻。'},

xiaochengqi:{syndrome:'阳明病 · 小承气汤（痞满为主）',symptoms:'腹胀满但不痛、大便硬、微烦、无潮热谵语',original:'《伤寒论》213条："阳明病，其人多汗，以津液外出，胃中燥，大便必硬……小承气汤主之。"',formula:'大黄12g 厚朴9g 枳实9g',method:'三味同煮，加水700ml煮剩300ml。分两次服，得下即停。',otc:'无成药——轻症可试用枳实导滞丸',hulao:'胡老说：痞满是主证——肚子胀大便硬但不痛。攻下力度比大承气汤温和。儿童便秘此方宜轻。',combo:'保持定时上厕所习惯，忌辛辣。',warning:'儿童用量减半，得下即停。'},

tiaoweichengqi:{syndrome:'阳明病 · 调胃承气汤（燥热在胃）',symptoms:'大便干结、心烦、不恶寒但热、腹胀不明显、舌红苔黄',original:'《伤寒论》248条："太阳病三日，发汗不解，蒸蒸发热者，属胃也，调胃承气汤主之。"',formula:'大黄12g 炙甘草6g 芒硝9g（冲服）',method:'先煮大黄甘草，去渣后溶入芒硝。小火少少温服。',otc:'三黄片（药性相近但非完全相同）',hulao:'胡老说：燥热主要在胃——心烦+不大便。肚子不胀是小承气和调胃承气的区别。',combo:'少吃辛辣油炸，多喝水。'},

maziren:{syndrome:'阳明病 · 麻子仁丸（润下/脾约）',symptoms:'老人产妇病后大便干结如羊屎、小便多、无明显腹胀痛',original:'《伤寒论》247条："趺阳脉浮而涩……大便则硬，其脾为约，麻子仁丸主之。"',formula:'火麻仁15g 杏仁9g 大黄9g 枳实6g 厚朴6g 芍药9g。有成药。',method:'成药按说明服用。汤剂：加水800ml煮剩300ml。',otc:'麻子仁丸（药店有售）',hulao:'胡老说：老年人习惯性便秘——大便是硬的但肚子不胀不痛。麻子仁丸润下，承气汤攻下，老年人慎用攻下。',combo:'麻子仁丸+蜂蜜水送服。'},

// ===================================================================
// 气滞二方（最常见于女性和职场人）
// ===================================================================

sinisan:{syndrome:'少阳病 · 四逆散（气秘）',symptoms:'便秘、大便不干但拉不出、腹胀打嗝放屁多、情绪波动加重、手脚偏凉',original:'《伤寒论》318条："少阴病，四逆，其人或咳或悸……四逆散主之。"',formula:'柴胡9g 枳实9g 芍药9g 炙甘草6g',method:'加水700ml煮剩300ml。',otc:'逍遥丸 / 木香顺气丸',hulao:'胡老说：气滞型便秘最多见于女性和职场人——便不干就是排不出。这不是没水行舟，是输送带停转了。四逆散疏肝理气，输送带一转大便就通。',combo:'逍遥丸+多走路促肠蠕动。'},

xiaochaihu:{syndrome:'少阳病 · 小柴胡汤（枢机不利便秘）',symptoms:'便秘+口苦咽干+胸胁苦满+没胃口+寒热往来',formula:'柴胡12g 黄芩9g 人参6g 半夏9g 炙甘草6g 生姜6g 大枣6g。便秘甚去人参加枳实。',method:'加水1000ml煮剩400ml，去渣再煎至300ml。',otc:'小柴胡颗粒',hulao:'胡老说：少阳枢机一转，三焦气机通达，大便自然通畅。口苦+便秘=少阳——不要只盯着大便。',combo:'小柴胡颗粒+保持定时上厕所习惯。'},

// ===================================================================
// 虚寒三方
// ===================================================================

dahuangfuzi:{syndrome:'少阴病 · 大黄附子汤（寒实便秘）',symptoms:'便秘+怕冷+手脚冰凉+腹痛胁下偏痛。大便不一定干！',original:'《金匮要略》："胁下偏痛，发热，其脉紧弦，此寒也，以温药下之，宜大黄附子汤。"',formula:'大黄9g 炮附子9g（先煎1小时） 细辛3g',method:'先煮附子1小时，后下大黄细辛。温下法——不同于承气汤的寒下。',otc:'无成药，需辨证使用',warning:'附子先煎1小时！大便不干+手脚冰凉=寒结——不能用清热通便法。手足温热者不可用。',hulao:'胡老说：大黄通便治标，附子温阳散寒治本，细辛散寒通络。温下法的代表方。',combo:'忌生冷，可配合艾灸关元穴。'},

lizhong:{syndrome:'太阴病 · 理中汤（脾虚便秘）',symptoms:'大便先干后稀、不太臭、怕冷、肚子隐痛喜按、口不渴、舌淡苔白',formula:'党参9g 干姜6g 炙甘草6g 生白术30-60g（大剂量生白术是关键！）',method:'加水700ml煮剩300ml。',otc:'理中丸 / 附子理中丸',hulao:'胡老说：先干后稀=脾虚运化无力。前面干了=脾不能把水运到大肠，后面稀了=脾不运水。生白术大量用可以通便——不是泻是健运。这是很多老中医的秘而不宣经验。',combo:'理中丸+多吃小米粥山药。忌生冷。'},

sini:{syndrome:'少阴病 · 四逆汤（阳气衰微重症）',symptoms:'完全不排便（肠道麻痹）、全身极度怕冷、四肢冰冷、脉微细、但欲寐（总想睡）',original:'《伤寒论》323条："少阴病，脉沉者，急温之，宜四逆汤。"',formula:'生附子9g（先煎1.5小时） 干姜9g 炙甘草12g',method:'先煮附子1.5小时（必须！），再下干姜甘草，煮取300ml。分温再服。',otc:'无成药——此为急救方，必须辨证使用',warning:'⚠️ 这是重症急救方！仅适用于全身阳气极度衰微者。普通便秘不可滥用！生附子必须先煎1.5小时去毒！手足温者不可用！',hulao:'胡老说：四逆汤治的是全身阳气衰微——肠道完全无力蠕动。这不是普通便秘，是危重证候。手足温的人绝对不能用！',combo:'需在中医师指导下使用。急症建议立即就医。'},

// ===================================================================
// 血虚 + 老人阳虚 + 儿童 + 表郁（新增六方）
// ===================================================================

danggui:{syndrome:'太阴病 · 当归芍药散（血虚便秘）',symptoms:'大便干涩难出、面色萎黄无华、月经量少色淡、皮肤干燥、舌淡苔白',original:'《金匮要略》当归芍药散——"妇人怀娠，腹中㽲痛"；亦治血虚水盛。',formula:'当归15-30g（大剂量润肠） 芍药15g 川芎9g 茯苓9g 白术9g 泽泻9g',method:'加水800ml煮剩300ml。',otc:'当归芍药散颗粒 / 八珍益母丸（相近）',hulao:'胡老说：血虚便秘=无水行舟。血足了肠道有了滋润大便自然通。面黄+月经少+便干=血虚，跟上火完全相反！当归是润肠关键。',combo:'多吃红枣桂圆猪肝。忌熬夜耗血。孕妇可用（养血安胎润肠）。'},

shenqi:{syndrome:'少阴病 · 肾气丸（老人阳虚便秘）',symptoms:'老人排便无力、怕冷畏寒、腰膝酸软、夜尿多、大便不一定干',original:'《金匮要略》肾气丸——"虚劳腰痛，少腹拘急，小便不利者，八味肾气丸主之。"',formula:'干地黄24g 山药12g 山茱萸12g 泽泻9g 茯苓9g 丹皮9g 桂枝3g 炮附子3g。有成药。',method:'成药按说明服用。汤剂：加水1000ml煮剩300ml。',otc:'金匮肾气丸 / 桂附地黄丸',hulao:'胡老说：老人便秘伴腰膝酸软+夜尿多=肾阳虚。肾主二便，肾阳不足则排便无力。肾气丸温补肾阳，阳气一足大便自然有力排出。',combo:'桂附地黄丸+每晚泡脚。忌生冷寒凉食物。'},

baohe:{syndrome:'太阴/阳明 · 保和丸（儿童食积便秘）',symptoms:'儿童便秘、不爱吃饭、肚子胀、口臭、大便酸臭或干结、舌苔厚腻',formula:'山楂15g 神曲9g 半夏6g 茯苓9g 陈皮6g 连翘6g 莱菔子9g。有成药。',method:'成药按说明服用（儿童用量减半）。汤剂：加水500ml煮剩150ml，分2-3次服。',otc:'保和丸 / 大山楂丸 / 小儿化食丸',hulao:'胡老说：小儿便秘最常见就是食积——吃多了不消化堵在肠道。保和丸消食导滞。不要一见便秘就用大黄！',combo:'保和丸+顺时针按摩肚子。晚餐减量，忌零食。',warning:'儿童用量减半。食积化热（发烧+大便不通）及时就医。'},

xiaojianzhong:{syndrome:'太阴病 · 小建中汤（儿童虚寒便秘）',symptoms:'儿童便秘、怕冷、肚子隐痛喜欢被揉、不爱吃饭、面色偏白、大便不一定干',original:'《伤寒论》100条："伤寒，阳脉涩阴脉弦，法当腹中急痛，先与小建中汤……"',formula:'桂枝9g 芍药18g 炙甘草6g 生姜9g 大枣6g 饴糖30g（药煮好溶入）',method:'前五味加水700ml煮剩300ml，去渣后溶入饴糖。分温服。',otc:'小建中颗粒 / 黄芪建中丸（相近）',hulao:'胡老说：小儿便秘不一定是上火——怕冷+肚子喜按=虚寒。小建中汤温中补虚，芍药加倍可缓急通便。甜甜的孩子爱喝。',combo:'小建中颗粒（甜的）+腹部热敷。忌生冷冰淇淋。'},

mahuang:{syndrome:'太阳病 · 麻黄汤（表郁便秘）',symptoms:'感冒/受凉后出现便秘、怕冷无汗、浑身酸痛、发热、气喘、舌淡苔白',original:'《伤寒论》35条："太阳病，头痛发热，身疼腰痛，骨节疼痛，恶风，无汗而喘者，麻黄汤主之。"',formula:'麻黄9g（去节） 桂枝6g 杏仁9g 炙甘草3g',method:'加水900ml先煮麻黄去浮沫，再下余药煮剩300ml。分温服，覆被取微汗。',otc:'风寒感冒颗粒（相近，非完全相同）',warning:'表邪便秘忌用大黄等攻下药——会引邪入里！必须先解表。高血压心脏病慎用麻黄。',hulao:'胡老说：表邪郁闭→肺气不降→大肠传导失常→便秘。这种便秘通便药没用——解表才是关键。一发汗表邪散了，肺气一降大便自然通。',combo:'喝热粥助发汗。忌吃泻药——此非燥结，解表自通。'}

}};

