dangguishaoyao:{syndrome:'太阴/少阴 · 当归芍药散（血虚水盛痛经）',symptoms:'经后隐痛、面色萎黄、轻度浮肿、头晕、月经量少色淡',original:'《金匮要略》当归芍药散——"妇人怀娠，腹中㽲痛"。',formula:'当归9g 芍药15g 川芎6g 茯苓9g 白术9g 泽泻9g——补血+利水',method:'加水800ml煮剩300ml。',otc:'当归芍药散颗粒 / 八珍益母丸',hulao:'胡老说：血虚+水盛=当归芍药散。面色萎黄是血虚，浮肿是水盛。和当归建中汤的区别——有无浮肿。'},
