// 痤疮（痘痘）经方辨证决策树 — 完全重写
// 参考：G:/老叶赚奶粉钱专用/老叶CC助手/中医/痤疮经方辨证速查表.md
// 第一问：痘痘形态（不是位置！）→ 第二问：位置或出汗/月经等
// 新增：桂麻各半汤、大黄黄连泻心汤、麻杏甘石汤、葛根汤、丹栀逍遥散、
//        甘草泻心汤、半夏泻心汤、理中汤
// 左右脸颊区分：右颊=肺热（麻杏甘石）、左颊=肝火（小柴胡）
// ===================================================================
TREES.acne = {
id:'acne',
nodes:{
// ===== Level 1: 痘痘形态（第一问）=====
start:{q:'痘痘长什么样？',hint:'看痘痘先看形态——红肿=热毒、闭口=毛孔不开、暗紫=瘀血、经前反复=冲任失调。胡老说："痘痘不是皮肤问题，是内脏问题的显示器。"形态决定大方向，位置决定具体方子。',opts:[
  {text:'闭合性粉刺（不红不肿、小颗粒、挤出来是米粒状）',icon:'⚪',next:'close_type'},
  {text:'红肿脓包型（又红又大又痛、有白色脓头）',icon:'🔴',next:'red_type'},
  {text:'暗紫/黑色痘印、囊肿型（痘印难消、颜色暗）',icon:'🟣',next:'purple_type'},
  {text:'反复长、此起彼伏、伴随月经周期',icon:'🔄',next:'cycle_type'}
]},

// ===== Branch 1: 闭合性粉刺 → 问出汗+大便 =====
close_type:{q:'出汗多不多？皮肤油不油？大便怎么样？',hint:'闭合粉刺不是"上火"——毛孔不开=油脂排不出=堵塞。少汗+干=毛孔郁闭（桂麻各半开门），油+便黏/痞满=脾胃湿热上蒸（甘草泻心偏腹泻、半夏泻心偏痞满），色淡+便稀=虚寒（理中汤——最易误诊！）。',opts:[
  {text:'很少出汗+皮肤偏干+粉刺密集+有时身上也痒',icon:'🏜️',next:'gmgeb_acne'},
  {text:'出汗正常+皮肤油腻+大便黏腻不成形+痘痘灼痛',icon:'🛢️',next:'gancaoxiexin_acne'},
  {text:'出汗正常+皮肤油腻+心下痞满堵闷+恶心+肠鸣',icon:'😮',next:'banxiaxiexin_acne'},
  {text:'痘痘色淡不红肿+大便稀溏+吃凉药/生冷后加重',icon:'🧊',next:'lizhong_acne'}
]},

// ===== Branch 2: 红肿脓包 → 问位置+伴随症状 =====
red_type:{q:'痘痘主要在哪个位置？有什么伴随症状？',hint:'红肿=热毒，但热在哪个脏腑？看位置——额头眉心=心胃火，右脸颊=肺热，左脸颊/太阳穴=肝火胆火，面部+脖子僵=太阳表实，满面部+便秘+体壮=表里俱实。',opts:[
  {text:'额头/眉心为主+口臭+便秘+舌红苔黄',icon:'🔥',next:'dahuanghuanglian_acne'},
  {text:'右脸颊为主+口渴+出汗+痰黄+舌红',icon:'😷',next:'maxingganshi_acne'},
  {text:'左脸颊/太阳穴为主+口苦咽干+情绪波动后加重',icon:'😤',next:'xiaochaihu_acne'},
  {text:'面部+脖子僵硬酸痛+不出汗+皮肤粗糙',icon:'💪',next:'gegentang_acne'},
  {text:'满面部成片红肿+便秘口臭+体质壮实+舌红苔黄',icon:'💥',next:'fangfeng_acne'}
]},

// ===== Branch 3: 暗紫痘印 → 问月经+痛经 =====
purple_type:{q:'月经怎么样？有没有痛经？面色如何？',hint:'痘印暗紫+经年不退=瘀血。痛经+血块=实瘀（桂枝茯苓丸），面黄+浮肿+月经量少=血虚水盛（当归芍药散），手掌烦热+小腹冷=冲任虚寒夹瘀（温经汤）。',opts:[
  {text:'月经有血块+痛经明显（刺痛固定）+面色晦暗+舌有瘀斑',icon:'🩸',next:'guizhifuling_acne'},
  {text:'面色萎黄+浮肿+月经量少色淡+眼袋明显+痘印淡暗',icon:'😔',next:'dangguishao_acne'},
  {text:'嘴唇暗紫+手掌烦热（傍晚加重）+小腹冷痛+月经不调',icon:'🤲',next:'wenjingtang_acne'}
]},

// ===== Branch 4: 月经周期 → 问经前伴随症状 =====
cycle_type:{q:'月经前后的具体表现？',hint:'痘痘随月经周期变化——经前一周爆痘+乳房胀痛+烦躁=肝气郁结（四逆散/丹栀逍遥散），经前爆痘+小腹冷痛+手脚冰凉=冲任虚寒（温经汤），色淡量少+面色萎黄=血虚水盛（当归芍药散）。',opts:[
  {text:'经前一周集中爆痘（下巴/下颌线/两颊）+乳房胀痛+烦躁易怒',icon:'😤',next:'sinisan_acne'},
  {text:'经前爆痘+小腹冷痛+手脚冰凉+手掌烦热',icon:'🥶',next:'wenjingtang_acne'},
  {text:'月经量少色淡+面色萎黄+浮肿+痘印淡而不消',icon:'😔',next:'dangguishao_acne'}
]},

// ================================================================
// LEAF NODES — 13方，每方含 syndrome/symptoms/original/formula/method/otc/hulao/combo/warning
// ================================================================

// --- 闭合粉刺 分支 ---

gmgeb_acne:{syndrome:'太阳病 · 桂枝麻黄各半汤（表郁轻证/毛孔不开）',symptoms:'闭合性粉刺密集、粟粒疹、不红不肿、很少出汗/不出汗、皮肤偏干、身痒、面色偏红',original:'《伤寒论》23条："面色反有热色者，未欲解也，以其不能得小汗出，身必痒，宜桂枝麻黄各半汤。"',formula:'桂枝6g 芍药6g 麻黄6g 杏仁6g 炙甘草3g 生姜6g 大枣4枚',method:'加水700ml煮剩300ml。微发汗——小发汗法，不是大汗，是"微汗法"。麻黄量不宜大。',otc:'无直接中成药',hulao:'胡老说：毛孔是皮肤的排泄通道，毛孔堵塞了油脂代谢谢不出去就会长闭口。这时候不是清热的问题——是"开门"的问题。麻黄开毛窍，桂枝通血脉，微微发汗把毛孔打开，闭口自然消了。',combo:'微发汗+忌辛辣油腻。洗澡水温不要太高。坚持1-2周可见闭口减少。'},

gancaoxiexin_acne:{syndrome:'太阴阳明合病 · 甘草泻心汤（脾胃湿热上蒸/偏腹泻）',symptoms:'口周下巴反复长痘、痘痘灼痛偏红、大便黏腻不成形/下利、腹中雷鸣、心下痞但不严重、舌苔黄腻、吃清热药容易腹泻',original:'《伤寒论》158条："伤寒中风，医反下之，其人下利日数十行，谷不化，腹中雷鸣，心下痞硬而满，干呕心烦不得安……甘草泻心汤主之。"',formula:'炙甘草12g（重用！）黄芩9g 干姜9g 半夏9g 黄连3g 人参6g 大枣4枚',method:'加水1000ml煮剩300ml。分两次温服。炙甘草必须重用——甘草泻心汤中甘草用四两，是普通量的2-3倍。',otc:'无直接中成药。需饮片煎煮。',hulao:'胡老说：下巴长痘是最容易被当成"上火"去乱吃清热药的类型。其实很多时候是脾胃湿热——湿热往上蒸腾，在口周下巴这个"脾胃的辖区"就变成了痘痘。甘草泻心重用炙甘草治黏膜病变，痘痘灼痛+腹泻的优先用此方。',combo:'甘草泻心汤煎服+忌生冷辛辣。反复发作超三个月建议坚持调理脾胃2-3个月。',warning:'甘草泻心汤是经方中甘草用量最大的方之一。高血压患者注意甘草可能引起水钠潴留。'},

banxiaxiexin_acne:{syndrome:'太阴阳明合病 · 半夏泻心汤（寒热错杂/偏痞满）',symptoms:'口周下巴痘痘、闭合粉刺/小痘为主、心下痞满堵闷感突出、恶心、肠鸣、舌苔黄白相间、大便偏软但不泻',original:'《伤寒论》149条："但满而不痛者，此为痞……宜半夏泻心汤。"',formula:'半夏12g 黄芩9g 干姜9g 人参9g 炙甘草6g 黄连3g 大枣4枚',method:'加水1000ml煮剩300ml。分两次温服。',otc:'半夏泻心汤颗粒（部分药店有）',hulao:'胡老说：痞满堵闷感比痘痘本身更突出时用半夏泻心。和甘草泻心汤的区别——甘草泻心重用炙甘草针对黏膜病变（痘痘灼痛+腹泻），半夏泻心治痞满+恶心+肠鸣为主。核心都是辛开苦降——干姜开+连芩降+参草枣补。',combo:'半夏泻心汤煎服+忌生冷辛辣。平时吃完饭不要立刻躺下。'},

lizhong_acne:{syndrome:'太阴病 · 理中汤（虚寒型痘痘/最易误治！）',symptoms:'痘痘色淡不红肿、迁延不愈、大便稀溏、口不渴、吃生冷/凉药后痘痘加重、舌淡苔白、手脚偏凉',original:'《伤寒论》386条："寒多不用水者，理中丸主之。"',formula:'党参9g 干姜6g 炙甘草6g 白术9g',method:'加水700ml煮剩300ml。分两次温服。',otc:'理中丸 / 附子理中丸',hulao:'胡老说：这是最容易被误治的类型。一看到痘痘就以为是上火，吃一堆凉药——结果越吃越重。虚寒体质的痘痘，本质是脾胃运化不好，湿浊废物排不出去，只能往脸上冒。理中汤暖了脾胃，运化恢复了，脸色自然干净。',combo:'理中丸+忌生冷食物。如果吃清热药后痘痘反而加重=明确信号说明不是实热，是虚寒！',warning:'吃清热药后痘痘反而加重——这是虚寒型的警报信号！千万不能再清热，方向反了越治越重。'},

// --- 红肿脓包 分支 ---

dahuanghuanglian_acne:{syndrome:'阳明病 · 大黄黄连泻心汤（心胃实热上炎）',symptoms:'额头眉心密集红痘、红肿疼痛、口臭、便秘、舌红苔黄、脉关上浮',original:'《伤寒论》154条："心下痞，按之濡，其脉关上浮者，大黄黄连泻心汤主之。"',formula:'大黄9g 黄连6g',method:'⚠️ 麻沸汤渍之——滚开水泡药5-10分钟，不要煮！取其轻清之气上行清热。煮久了药性下沉不走面部。这是经方煎服法的精妙之处。',otc:'黄连上清片 / 三黄片',hulao:'胡老说：额头眉心属心胃——心胃之火往上攻就变成眉心痘。麻沸汤渍之取轻清之气走上焦，开水泡泡就行，煮了就下沉不走头面了。',combo:'开水泡服大黄黄连+忌辛辣油炸。保持大便通畅。'},

maxingganshi_acne:{syndrome:'阳明病 · 麻杏甘石汤（肺热上蒸面部）',symptoms:'右脸颊痘痘为主（肺之应）、汗出、口渴、痰黄、舌红苔黄、可能伴呼吸系统症状',original:'《伤寒论》63条："汗出而喘，无大热者，可与麻黄杏仁甘草石膏汤。"',formula:'麻黄9g 杏仁9g 炙甘草6g 石膏30g',method:'加水800ml煮剩300ml。分两次温服。',otc:'清肺抑火片 / 双黄连口服液',hulao:'胡老说：右脸颊属肺——右脸颊反复长痘伴呼吸系统症状，从肺治。肺热清了，脸上自然干净。',combo:'清肺抑火片+戒糖戒奶。配合呼吸系统健康管理。右脸颊痘反复不愈查一下呼吸道。'},

xiaochaihu_acne:{syndrome:'少阳病 · 小柴胡汤（胆火/肝火上炎）',symptoms:'太阳穴痘痘、左脸颊痘痘、口苦咽干、情绪波动后加重、胸胁苦满、经前可能加重、脉弦',original:'《伤寒论》96条："伤寒五六日中风，往来寒热，胸胁苦满，嘿嘿不欲饮食，心烦喜呕……小柴胡汤主之。"',formula:'柴胡12g 黄芩9g 半夏9g 人参6g 炙甘草6g 生姜9g 大枣4枚。痘痘红肿明显加连翘、薏苡仁清热排脓。',method:'加水1000ml煮剩300ml。分两次温服。',otc:'小柴胡颗粒+皮肤病血毒丸',hulao:'胡老说：面部两侧是少阳经循行路线——左脸颊/太阳穴长痘就是肝火胆火。小柴胡汤疏解少阳郁热，痘痘自然消退。右脸颊=肺热，左脸颊=肝火，这是中医面诊的基本功。',combo:'小柴胡颗粒+保持情绪稳定+早睡。经前烦躁时尤其适合。'},

gegentang_acne:{syndrome:'太阳病 · 葛根汤（表实+津液不升）',symptoms:'面部（尤其是额头、两颊）痘痘、项背强急（脖子发僵）、无汗、皮肤粗糙',original:'《伤寒论》31条："太阳病，项背强几几，无汗恶风，葛根汤主之。"',formula:'葛根12g 麻黄9g 桂枝6g 芍药6g 炙甘草6g 生姜9g 大枣12枚',method:'加水1000ml先煮葛根、麻黄去上沫，再加余药煮剩300ml。分两次温服。',otc:'葛根汤颗粒',hulao:'胡老说：葛根能升津液上达头面，改善面部血液循环和代谢谢。日本人常用葛根汤加薏苡仁治粉刺。脖子僵+面部痘=葛根汤证。',combo:'葛根汤颗粒+注意颈部保暖。多做颈部拉伸。'},

fangfeng_acne:{syndrome:'太阳阳明合病 · 防风通圣散（表里双解第一方）',symptoms:'脓疱型痤疮（红肿、有脓头）、便秘、口臭、皮肤油腻、体质壮实、舌红苔黄、痘痘成片密集',formula:'防风通圣散（后世方）：防风 荆芥 麻黄 连翘 栀子 大黄 芒硝 石膏 黄芩 桔梗 川芎 当归 白芍 白术 滑石 甘草',method:'中成药按说明服用。',otc:'防风通圣丸',hulao:'胡老说："有病没病防风通圣"——日本人说此方对皮肤病效果非常广泛。表里双解，既有麻黄荆芥防风发散表邪，又有大黄芒硝通下里热。壮实人大便秘结的痤疮首选。',combo:'防风通圣丸+多喝水+戒油炸辛辣。保持每天大便通畅。'},

// --- 暗紫痘印 分支 ---

guizhifuling_acne:{syndrome:'瘀血证 · 桂枝茯苓丸（瘀血型痘印）',symptoms:'痘印暗紫色/黑色、久不消退、囊肿型痤疮、月经有血块+痛经（刺痛固定）、面色晦暗、舌有瘀斑/瘀点',original:'《金匮要略》桂枝茯苓丸方',formula:'桂枝9g 茯苓9g 丹皮9g 桃仁9g 芍药9g',method:'加水700ml煮剩300ml。分两次温服。',otc:'桂枝茯苓丸',hulao:'胡老说："久病必瘀"——痘痘反复多年不愈，痘印一直是暗的、黑的，就是瘀血。桂枝茯苓丸把瘀血化开，新鲜血液才能流过去修复皮肤。和温经汤鉴别：桂苓丸偏实瘀（痛经+血块），温经汤偏虚寒夹瘀（小腹冷+手掌烦热）。',combo:'桂枝茯苓丸+维生素C。痘印消退需1-3个月坚持，不要急于求成。'},

dangguishao_acne:{syndrome:'太阴病 · 当归芍药散（血虚水盛）',symptoms:'面色萎黄+浮肿、月经量少色淡、眼袋明显、痘印淡暗不消、白带量多清稀、舌淡胖苔白',original:'《金匮要略》当归芍药散方',formula:'当归9g 芍药15g 川芎6g 茯苓9g 白术9g 泽泻9g',method:'加水800ml煮剩300ml。分两次温服。',otc:'当归芍药散颗粒 / 八珍益母丸',hulao:'胡老说："血不利则为水"——血虚和水饮往往同时出现。很多女性痘痘+面色黄+浮肿+月经量少，这种不是上火，是血虚+水湿。当归芍药散养血利水，皮肤会从黄暗变得明润。',combo:'当归芍药散+保证睡眠+适当补血食物（红枣桂圆等）。'},

wenjingtang_acne:{syndrome:'太阴/厥阴 · 温经汤（冲任虚寒夹瘀+虚热上扰）',symptoms:'下颌线/下巴/颈部反复长痘、手掌烦热（傍晚加重）、唇口干燥、小腹冷痛、月经不调、痘痘时红时暗',original:'《金匮要略》："妇人年五十所，病下利数十日不止，暮即发热，少腹里急，腹满，手掌烦热，唇口干燥……当以温经汤主之。"',formula:'吴茱萸9g 当归6g 川芎6g 芍药6g 人参6g 桂枝6g 阿胶6g（烊化）丹皮6g 生姜6g 半夏6g 麦冬15g 甘草6g',method:'加水1200ml煮剩400ml，阿胶烊化冲入。分三次温服。',otc:'温经丸 / 艾附暖宫丸（类似方向）',hulao:'胡老说：手掌烦热、嘴唇干是假热——根在下寒。傍晚手心发热是特征。下颌线的痘痘跟冲任二脉关系最大，从冲任调治才能断根。',combo:'温经汤+经期保暖。忌生冷。',warning:'手掌烦热+唇干看上去像"上火"——但千万不能用清热药！根在下寒，清热只会加重。'},

// --- 月经周期 分支 ---

sinisan_acne:{syndrome:'少阳病 · 四逆散/丹栀逍遥散（肝气郁结）',symptoms:'经前一周集中爆痘（下巴、下颌线、两颊）、乳房胀痛、烦躁易怒、手足不温（气郁非阳虚）、脉弦',original:'《伤寒论》318条："少阴病，四逆，其人或咳，或悸，或小便不利，或腹中痛，或泄利下重者，四逆散主之。"',formula:'四逆散：柴胡9g 枳实9g 芍药9g 炙甘草6g。加丹皮、栀子即成丹栀逍遥散，清肝解郁力量更强。',method:'加水700ml煮剩300ml。分两次温服。',otc:'加味逍遥丸 / 丹栀逍遥丸',hulao:'胡老说：经前一周痘痘大爆发+乳房胀痛+烦躁——典型的肝气郁结。四逆散疏肝理气比任何祛痘药都好用。气顺了火自然降，痘痘自然消。',combo:'加味逍遥丸+保持情绪稳定+经前少吃甜食和奶制品。'}

}};

// ===================================================================
TREES.ulcer = {
id:'ulcer',
nodes:{
// Level 1: 辨寒热——最高原则
start:{q:'溃疡是什么颜色？痛不痛？大便怎样？',hint:'胡老说口疮第一辨——寒热。口腔溃疡≠上火！鲜红灼痛=热证；淡白不痛=寒证。关键看三点：溃疡颜色（红=热/淡=寒）、大便（干=热/稀=寒）、全身寒热（怕冷还是怕热）。方向错了全白治——寒证用清热药越治越烂。',opts:[
  {text:'鲜红+灼痛+周围红肿+大便偏干或正常',icon:'🔴',next:'reshi_or_xure'},
  {text:'淡白/淡红+不太痛+周围不红+大便偏稀',icon:'⚪',next:'cold_or_cuozong'}
]},

// Level 2 (红/热): 实热还是虚热？
reshi_or_xure:{q:'舌头整体什么样？手脚热还是凉？',hint:'热证分虚实——舌红苔黄=实热（用清热泻火）；舌红少苔=虚热（用滋阴降火）。实热用大黄黄连，虚热用知柏地黄。方向一定要对。',opts:[
  {text:'舌红苔黄厚+口臭+大便干+手脚不凉',icon:'🔥',next:'shiren'},
  {text:'舌红但苔很少/无苔+手心热+口干但不爱喝水+腰酸盗汗',icon:'🌙',next:'xuren'}
]},

// === 实热分支 ===
shiren:{q:'溃疡主要在什么位置？发了几个？',hint:'实热口疮看位置和数量——舌尖=心火（导赤散）；牙龈唇内=脾胃热（三黄泻心）；满口多处=三焦热毒（黄连解毒）；咽喉上颚=上焦热（竹叶石膏）。胡老说大黄黄连泻心汤必须用开水泡——煮了药性下沉反而不走口腔。',opts:[
  {text:'舌尖/舌边+心烦失眠+小便短赤',icon:'👅',next:'daochisan'},
  {text:'牙龈肿痛/唇内/两颊+口臭+便秘+1-3个溃疡',icon:'🦷',next:'dahuanghuanglian'},
  {text:'满口多处溃疡（好几个同时发）+灼痛剧烈+面红口臭+便秘严重',icon:'😫',next:'sanhuangxiexin'},
  {text:'咽喉附近/上颚+口干舌燥+可能刚发过烧',icon:'🗣️',next:'zhuye_ulcer'}
]},
daochisan:{syndrome:'心经热证 · 导赤散（心火上炎/心火下移小肠）',symptoms:'舌尖溃疡（舌尖属心）、心烦失眠、小便短赤涩痛、舌红（舌尖尤甚）',formula:'导赤散：生地15g 木通6g 竹叶9g 甘草梢6g',method:'加水500ml煮剩200ml。分两次温服。',otc:'导赤丸',hulao:'胡老说：舌尖属心。舌尖溃疡+小便黄赤=心火下移小肠。导赤散既清心火又利小便——心火从小便走。',combo:'导赤丸+多喝水。少吃辣。小便不黄了溃疡就好了。'},
dahuanghuanglian:{syndrome:'阳明病 · 大黄黄连泻心汤（上焦实热/轻症口疮）',symptoms:'口腔溃疡鲜红灼痛、牙龈肿痛/出血、口臭、便秘、舌红苔黄、体质壮实',original:'《伤寒论》154条："心下痞，按之濡，其脉关上浮者，大黄黄连泻心汤主之。"',formula:'大黄9g 黄连6g',method:'⚠️ 关键煎法——"麻沸汤渍之"：滚开水泡药，不要煮！泡5-10分钟即可。取其轻清之气上行清热。煮久了药性下沉不走口腔。',otc:'黄连上清片（轻症参考）',hulao:'胡老说：体质壮实之人初发口疮常是此证。用开水泡不用煮——这是经方煎服法的精妙之处。',combo:'开水泡服大黄黄连+饭后盐水漱口。忌辛辣油炸。'},
sanhuangxiexin:{syndrome:'阳明病 · 三黄泻心汤（三焦热毒/多发口疮）',symptoms:'满口多处溃疡同时发好几个、灼痛剧烈不能吃东西、口气热臭、面红目赤、便秘尿黄、舌红绛苔黄',original:'《金匮要略》泻心汤方——大黄、黄连、黄芩。比大黄黄连泻心汤多一味黄芩，清三焦热力量更强。',formula:'大黄9g 黄连6g 黄芩6g——滚开水泡服，不用煮！',method:'⚠️ 麻沸汤渍之——滚开水泡药5-10分钟即可，不可久煮。取其轻清之气上行清热。',otc:'三黄片（轻症）/ 黄连解毒丸',hulao:'胡老说：口臭+牙龈肿+满口多发=胃热上冲整个口腔。这是实热口疮里最重的一级。开水泡服取轻清之气——煮了就下沉不走口腔了。',combo:'三黄片+饭后盐水漱口。忌辛辣油炸。如果吃完拉肚子就减量或停药。'},
zhuye_ulcer:{syndrome:'阳明病后期 · 竹叶石膏汤（病后余热口疮/气阴两虚）',symptoms:'病后/发热后出现口腔溃疡、人很虚弱疲惫、气逆欲吐、口渴、舌红少苔',original:'《伤寒论》397条："伤寒解后，虚羸少气，气逆欲吐，竹叶石膏汤主之。"',formula:'竹叶10g 石膏30g 半夏9g 麦冬15g 人参6g 炙甘草6g 粳米15g',method:'加水1200ml煮到米熟（约剩500ml）。分三次温服。',otc:'生脉饮（益气养阴方向）',hulao:'胡老说：感冒发烧后口腔溃疡此方首选——病后体虚+余热未清。和知柏地黄丸的慢性腰酸盗汗完全不同。'},

// === 虚热分支 ===
xuren:{q:'虚热口疮的最明显特征是？',hint:'虚热口疮分四路——腰酸盗汗=肾阴虚（知柏地黄丸）；咽喉干燥唇干=肺胃阴虚（麦门冬汤）；病后体虚=气阴两虚（竹叶石膏汤）；手脚凉+清热无效=虚阳上浮（封髓丹）。胡老说反复口疮用知柏地黄丸最多见。',opts:[
  {text:'腰膝酸软+潮热盗汗+反复发作经久不愈',icon:'🦵',next:'zhibaidihuang'},
  {text:'咽喉干燥不利+嘴唇干脱皮+干咳少痰',icon:'🏜️',next:'maimen_ulcer'},
  {text:'病后/劳累后发作+体虚乏力+气逆欲吐',icon:'😮',next:'zhuye_ulcer'},
  {text:'手脚偏凉（上热下寒）+用清热药没效果+用温补药又加重',icon:'🤲',next:'fengsuidan'}
]},
zhibaidihuang:{syndrome:'少阴病 · 知柏地黄丸（肾阴虚/虚火上炎）',symptoms:'反复口腔溃疡经久不愈、腰膝酸软、潮热盗汗、手足心热、舌红少苔、脉细数',formula:'知柏地黄丸（后世方）：六味地黄丸加知母、黄柏。',method:'成药直接按说明服用。',otc:'知柏地黄丸',hulao:'胡老说：口疮+腰酸盗汗=肾阴虚。和甘草泻心汤最关键的区别——知柏地黄丸毫无消化道症状（无心下痞无肠鸣无腹泻）。',combo:'知柏地黄丸+忌熬夜。'},
maimen_ulcer:{syndrome:'阳明病虚热 · 麦门冬汤（肺胃阴虚/虚火上炎）',symptoms:'口腔溃疡+咽喉干燥不利、唇干脱皮、干咳少痰、舌红少苔、手足心热',original:'《金匮要略》："大逆上气，咽喉不利，止逆下气者，麦门冬汤主之。"',formula:'麦冬35g 半夏6g 人参6g 炙甘草6g 粳米15g 大枣4枚',method:'加水1200ml煮到米熟（约剩500ml）。分三次温服。',otc:'养阴清肺丸',hulao:'胡老说：麦门冬汤治肺胃阴虚——咽喉不利感比腰酸更突出。和知柏地黄丸比：一个看咽喉（麦门冬），一个看腰（知柏）。'},
fengsuidan:{syndrome:'少阴病 · 封髓丹（虚阳上浮/相火妄动）',symptoms:'口腔溃疡反复、手足不温/偏凉（上热下寒）、清热药无效温补药加重、脉沉弱',formula:'封髓丹（后世方）：黄柏9g 砂仁6g 炙甘草6g',method:'加水500ml煮剩200ml。分两次温服。',otc:'无直接中成药。参考知柏地黄丸。',hulao:'蒲辅周先生善用此方治反复口疮。关键眼目——口疮+手脚凉+用清热药没用=虚阳上浮。不是真热是虚火，要"引火归元"而不是清热。'},

// === 寒证/淡白分支 ===
cold_or_cuozong:{q:'溃疡是第几次发？肚子有什么不舒服？',hint:'淡白不痛的口疮分两路——寒热错杂（反复发作+胃不舒服+大便不成形=甘草泻心汤）和纯虚寒（不反复+怕冷+大便稀溏=理中汤）。胡老说反复口疮十个有七八个是甘草泻心汤证！这是口腔溃疡最重要的一个方。',opts:[
  {text:'反复发作+胃堵闷+肚子里咕噜响+大便不成形/拉肚子',icon:'🔄',next:'gancaoxiexin_lu'},
  {text:'初次或偶尔发作+没有胃不舒服+怕冷+大便稀溏',icon:'🧊',next:'lizhong_ulcer_lu'}
]},

// 甘草泻心汤 vs 半夏泻心汤
gancaoxiexin_lu:{q:'胃是堵闷为主还是肠鸣腹泻为主？溃疡痛得厉害吗？',hint:'甘草泻心汤和半夏泻心汤都是寒热错杂——但甘草泻心汤重用炙甘草（四两），专门解毒缓急治黏膜病变。口疮痛得厉害的用甘草泻心，痞满堵闷更突出的用半夏泻心。',opts:[
  {text:'溃疡灼痛+胃堵但不严重+肠鸣+大便不成形',icon:'🎯',next:'gancaoxiexin'},
  {text:'心下痞满堵闷感更突出+恶心+溃疡痛不剧烈',icon:'😮',next:'banxiaxiexin_kc'}
]},
gancaoxiexin:{syndrome:'太阴阳明合病 · 甘草泻心汤（口疮第一方/寒热错杂专属）',symptoms:'口腔溃疡反复发作、灼痛、心下痞满、腹中雷鸣、大便不成形/下利、吃凉药加重腹泻',original:'《伤寒论》158条："伤寒中风，医反下之，其人下利日数十行，谷不化，腹中雷鸣，心下痞硬而满，干呕心烦不得安……甘草泻心汤主之。"',formula:'炙甘草12g（重用！）黄芩9g 干姜9g 半夏9g 黄连3g 人参6g 大枣4枚',method:'加水1000ml煮剩300ml。分两次温服。',otc:'无直接中成药。甘草泻心汤需饮片煎煮。',hulao:'胡老说：反复发作的口腔溃疡，十个有七八个是甘草泻心汤证！吃凉药（清热药）会加重腹泻，吃热药（温补药）会加重溃疡。核心矛盾——中焦寒导致上焦虚火。炙甘草要用到四两（约12g），是普通甘草用量的2-3倍。',combo:'甘草泻心汤煎服+忌生冷辛辣。反复发作超一个月建议查免疫功能。',warning:'甘草泻心汤是经方中甘草用量最大的方之一。高血压患者注意甘草可能引起水钠潴留。'},
banxiaxiexin_kc:{syndrome:'太阴阳明合病 · 半夏泻心汤（偏痞满重/寒热错杂）',symptoms:'口腔溃疡、心下痞满堵闷感突出、恶心、肠鸣、舌苔黄白相间',original:'《伤寒论》149条："但满而不痛者，此为痞……宜半夏泻心汤。"',formula:'半夏12g 黄芩9g 干姜9g 人参9g 炙甘草6g 黄连3g 大枣4枚',method:'加水1000ml煮剩300ml。分两次温服。',hulao:'胡老说：痞满感比溃疡本身更突出的用半夏泻心。和甘草泻心汤的区别——甘草泻心重用炙甘草针对黏膜病变（溃疡灼痛），半夏泻心黄连量较大针对痞满。'},

// 纯虚寒分支
lizhong_ulcer_lu:{q:'怕不怕冷？大便什么情况？手脚凉不凉？',hint:'纯虚寒口疮——溃疡色淡不红+大便稀溏+怕冷。理中汤（脾胃虚寒）和四逆汤（全身阳虚）的区别在于程度。胡老说口疮久了反复用清热药无效+大便一直稀=必须考虑虚寒！',opts:[
  {text:'怕冷+大便稀溏+手脚不太凉+溃疡色淡白',icon:'🥶',next:'lizhong_kc'},
  {text:'极度怕冷+四肢冰冷+大便水样+精神萎靡+溃疡久不收口',icon:'🧊',next:'sinitang'}
]},
lizhong_kc:{syndrome:'太阴病 · 理中汤（虚寒口疮/最易误治）',symptoms:'口腔溃疡色淡不红、疼痛不剧、口不渴、大便稀溏、四肢不温、吃凉药凉食加重',original:'《伤寒论》386条："寒多不用水者，理中丸主之。"',formula:'党参9g 干姜6g 炙甘草6g 白术9g',method:'加水700ml煮剩300ml。分两次温服。',otc:'理中丸 / 附子理中丸',hulao:'胡老说：口疮久了反复用清热药无效+大便一直稀=必须考虑虚寒！很多人看到"炎症"就猛吃清热药，结果越吃越严重——这就是辨证方向错了。',combo:'理中丸+忌生冷食物。如果吃清热药后口腔溃疡加重=明确信号说明不是实热。'}
}};

