TREES.hypertension = {
id:'hypertension',
nodes:{
start:{q:'你的体型和体质大致是什么样的？伴随什么最明显？',hint:'胡老说中医不治"高血压"指标——治的是导致血压升高的那个人。血压为什么高？身体某处堵了心脏必须加压泵血。实证=堵（大柴胡合桂苓）、阳虚=水排不出去（真武汤）、痰湿=血管里痰多（半夏白术天麻）、气郁=情绪拉开血压（柴胡加龙骨牡蛎）。⚠️ 不可自行停药！',opts:[
  {text:'体型壮实+面色红+容易便秘+心烦胸胁满',icon:'💪',next:'shizheng'},
  {text:'体型浮肿+怕冷+夜尿多+乏力头晕',icon:'🦵',next:'yangxu'},
  {text:'体型肥胖+痰多+眩晕如坐船+舌苔厚腻',icon:'😵',next:'tanshi'},
  {text:'情绪波动大+易怒心烦+心悸失眠',icon:'😤',next:'qiyu'}
]},
shizheng:{q:'便秘严重吗？有没有固定刺痛或舌暗？',hint:'实证高血压分——单纯少阳阳明（大柴胡单方）和兼有瘀血（大柴胡合桂枝茯苓丸）。久病必瘀——高血压多年的十有八九要加活血药。胡老治高血压王牌组合就是大柴胡合桂苓。',opts:[
  {text:'便秘+口苦+胸胁满+呕不止+脉弦数有力',icon:'💢',next:'dachaihu_danc'},
  {text:'便秘+口苦+胸胁满+舌暗瘀斑+病程长+可能有固定刺痛',icon:'📍',next:'dachaihu_gfl'}
]},
dachaihu_danc:{syndrome:'少阳阳明合病 · 大柴胡汤单方（实证高血压偏气郁型）',symptoms:'高血压、便秘、呕不止、心下急满、口苦、脉弦数有力',formula:'柴胡15g 黄芩9g 芍药9g 半夏9g 枳实9g 大黄6g 生姜15g 大枣4枚',method:'加水1000ml煮剩300ml。分两次温服。',otc:'需医生处方',warning:'⚠️ 高血压不可自行停药换药。大柴胡汤含大黄，需医生确定用量。',hulao:'胡老说：壮实人高血压偏气郁便秘的用大柴胡单方。如果同时有舌暗瘀斑或病程多年，必须合桂枝茯苓丸活血。'},
dachaihu_gfl:{syndrome:'少阳阳明合病+瘀血 · 大柴胡汤合桂枝茯苓丸（胡希恕治高血压王牌组合）',symptoms:'高血压、体质壮实偏胖、面色红赤、大便秘结（必见！）、胸胁苦满、心下急、口苦咽干、烦躁易怒、舌暗红苔黄',formula:'大柴胡汤合桂枝茯苓丸——胡希恕先生治高血压最常用合方。',method:'大柴胡汤+桂枝茯苓丸同煎。加水1200ml煮剩400ml。',otc:'需医生处方。轻症可参考牛黄降压丸。',warning:'⚠️ 需医生处方。不可自行停药。',hulao:'胡老说：这种患者肚子里堵着（便秘+腹满）+情绪激动（少阳）+时间长了瘀血（桂苓）。大柴胡疏解少阳通下阳明=减压，桂苓活血化瘀=通络。很多患者吃一段时间血压下来了脾气也变好了。',compare:'🔸 大柴胡单方 vs 大柴胡合桂苓：病程短+舌不暗=单方；病程多年+舌暗瘀斑=合方\n🔸 大柴胡合桂苓 vs 真武汤：壮实面红便秘=大柴桂苓（实热瘀）；浮肿怕冷乏力=真武汤（阳虚水泛）'},
yangxu:{q:'浮肿主要在哪儿？头晕是什么感觉？',hint:'阳虚水泛=水排不出去堵在血管里→血压高。分真武汤（阳虚水泛全身）和苓桂术甘（水饮上冲→起则头眩）。',opts:[
  {text:'全身浮肿+怕冷+夜尿多+心悸+头晕沉',icon:'🦵',next:'zhenwuxg'},
  {text:'起身时头晕天旋地转+心悸+气上冲胸+浮肿不重',icon:'💫',next:'lingguizhugan_xg'}
]},
zhenwuxg:{syndrome:'少阴病 · 真武汤（阳虚水泛高血压）',symptoms:'高血压、浮肿、怕冷、夜尿多、头晕、心悸、小便不利、脉沉微、舌淡胖',original:'《伤寒论》316条——真武汤。',formula:'炮附子9g(先煎1h) 茯苓9g 芍药9g 白术9g 生姜9g',method:'先煮附子1小时（必须！），加其他药煮30分钟。分两次温服。',otc:'需医生处方',warning:'⚠️ 需医生指导。附子先煎1小时。不可自行停药。',hulao:'胡老说：浮肿+怕冷+高血压=阳虚水泛。水排不出去血管里压力就高。真武汤温阳利水——水排出去了血压自然降。跟大柴胡合桂苓的实证完全相反。'},
lingguizhugan_xg:{syndrome:'太阴病 · 苓桂术甘汤（水饮上冲高血压）',symptoms:'高血压、起则头眩（站起来头晕加重）、心悸、气上冲胸、舌淡胖苔白滑',original:'《伤寒论》67条："心下逆满，气上冲胸，起则头眩……苓桂术甘汤主之。"',formula:'茯苓12g 桂枝9g 白术9g 炙甘草6g',method:'加水800ml煮剩300ml。分两次温服。',warning:'⚠️ 需医生指导。不可自行停药。'},
tanshi:{q:'眩晕的特点是什么？有没有呕吐？',hint:'痰湿高血压分——半夏白术天麻（眩晕如坐船+痰多）、泽泻汤（支饮眩晕+站立不稳）。',opts:[
  {text:'眩晕像在船上+痰多胸闷恶心+舌苔厚腻+体型肥胖',icon:'😵',next:'banxiabaizhu'},
  {text:'站立不稳+眩晕+心悸+舌胖大水滑',icon:'🌊',next:'zexietang'}
]},
banxiabaizhu:{syndrome:'太阴病 · 半夏白术天麻汤（痰湿上蒙高血压）',symptoms:'高血压、肥胖、痰多、眩晕头重如裹、胸闷恶心、舌苔厚腻、脉弦滑',formula:'半夏9g 白术9g 天麻6g 茯苓9g 橘红6g 甘草3g 生姜3片 大枣3枚',method:'加水800ml煮剩300ml。',otc:'半夏天麻丸',warning:'⚠️ 需医生指导。不可自行停药。'},
zexietang:{syndrome:'太阴病 · 泽泻汤（支饮眩晕高血压）',symptoms:'高血压、眩晕站立不稳、心悸、舌胖大水滑',original:'《金匮要略》："心下有支饮，其人苦冒眩，泽泻汤主之。"',formula:'泽泻15g 白术6g',method:'加水500ml煮剩200ml。分两次温服。',warning:'⚠️ 需医生指导。不可自行停药。',hulao:'胡老说：泽泻汤只有两味药——专门治"支饮"引起的眩晕。和半夏白术天麻的痰湿多不同——泽泻汤偏水饮，半夏白术天麻偏痰湿。'},
qiyu:{q:'情绪相关的具体表现是？',hint:'气郁高血压分——柴胡加龙骨牡蛎（烦惊+心悸失眠）和四逆散（单纯气郁+手足凉）。',opts:[
  {text:'又烦又怕+心悸失眠+容易被吓+胸闷',icon:'😨',next:'chailongxg'},
  {text:'胀+打嗝+情绪波动加重+手足不温',icon:'😤',next:'sinisan_xg'}
]},
chailongxg:{syndrome:'少阳病 · 柴胡加龙骨牡蛎汤（烦惊高血压）',symptoms:'高血压、情绪波动大、易怒、心烦、失眠、心悸、胸闷、容易受惊',formula:'柴胡12g 龙骨15g 牡蛎15g 黄芩9g 桂枝6g 茯苓9g 半夏9g 大黄6g 人参6g',method:'加水1200ml煮剩500ml。分两次温服。',otc:'松龄血脉康胶囊',warning:'⚠️ 需医生指导。不可自行停药。',hulao:'胡老说：情绪波动+高血压=少阳。"烦惊"——又烦躁又容易受惊。情绪稳了血压自然稳。'},
sinisan_xg:{syndrome:'少阳病 · 四逆散（气郁高血压）',symptoms:'高血压、情绪波动加重、脘腹胀、打嗝、手足不温',formula:'柴胡9g 枳实9g 芍药9g 炙甘草6g',method:'加水700ml煮剩300ml。',otc:'逍遥丸（轻症参考）',warning:'⚠️ 需医生指导。不可自行停药。'}
}};

