TREES.diabetes = {
id:'diabetes',
nodes:{
start:{q:'得糖尿病多久了？"三多"（多饮多食多尿）里哪个最明显？',hint:'胡老说消渴分上中下三消+看阶段。上消口渴（肺）=白虎加人参；中消善饥（胃）=白虎汤/调胃承气；下消多尿（肾）=肾气丸。初期多实证（阳明），后期多虚证（少阴），久病必瘀（桂枝茯苓丸）。⚠️ 糖尿病需医生管理！不可自行停药！',opts:[
  {text:'口渴得厉害+老想喝水+口干舌燥',icon:'🚰',next:'shangxiao'},
  {text:'老是饿+吃很多还是饿',icon:'🍽️',next:'zhongxiao'},
  {text:'多尿+夜尿多+消瘦+怕冷乏力',icon:'🚽',next:'xiaxiao'},
  {text:'得病多年+出现并发症（浮肿/麻木/视力下降）',icon:'⏰',next:'complication'}
]},
shangxiao:{syndrome:'阳明病 · 白虎加人参汤（上消/消渴第一方）',symptoms:'极度口渴、口干舌燥、欲饮水数升、舌红苔黄燥、可能大汗',original:'《伤寒论》222条："若渴欲饮水，口干舌燥者，白虎加人参汤主之。"',formula:'石膏30-60g 知母18g 炙甘草6g 粳米30g 人参9g',method:'加水1200ml煮到米熟汤成（约剩500ml）。分三次温服。',otc:'玉泉丸。⚠️ 消渴丸含西药格列本脲不可与西药同服！',warning:'⚠️ 糖尿病不可自行停药。消渴丸含西药降糖成分格列本脲——与西药同服可致严重低血糖！所有用药方案由内分泌科医生确定。',hulao:'胡老说：白虎加人参汤是《伤寒论》治消渴第一方。口渴欲饮水数升——这是特征。'},
zhongxiao:{q:'有没有便秘？大便干不干？',hint:'中消分两种——有便秘（胃热+燥结=调胃承气汤），无便秘（纯胃热=白虎汤）。',opts:[
  {text:'大便秘结+口干+舌红苔黄',icon:'💢',next:'tiaowei_tnb'},
  {text:'大便正常+单纯善饥多食+舌红',icon:'🔥',next:'baihu_tnb'}
]},
tiaowei_tnb:{syndrome:'阳明病 · 调胃承气汤（中消/胃热消谷+燥结）',symptoms:'善饥多食、便秘、口干、舌红苔黄',formula:'大黄12g 炙甘草6g 芒硝9g(冲服)',method:'先煮大黄甘草，去渣加芒硝溶化。',warning:'⚠️ 需医生指导。不可自行停药。'},
baihu_tnb:{syndrome:'阳明病 · 白虎汤（中消/纯胃热无燥结）',symptoms:'善饥多食、舌红苔黄、大便正常',formula:'石膏50g 知母18g 炙甘草6g 粳米30g',method:'加水1200ml煮到米熟（约剩500ml）。分三次温服。',warning:'⚠️ 需医生指导。不可自行停药。'},
xiaxiao:{syndrome:'少阴病 · 肾气丸（下消/肾虚不固）',symptoms:'多尿、夜尿多、消瘦、怕冷、乏力、腰膝酸软',formula:'肾气丸：熟地24g 山茱萸12g 山药12g 泽泻9g 茯苓9g 丹皮9g 桂枝3g 炮附子3g',method:'加水1200ml煮剩400ml。分两次温服。',otc:'金匮肾气丸',warning:'⚠️ 需医生指导。不可自行停药。'},
complication:{q:'具体是什么并发症？',hint:'糖尿病后期三大并发症——肾病（浮肿=真武汤/五苓散）、神经病变（四肢麻木=黄芪桂枝五物汤）、血管病变（瘀血=桂枝茯苓丸）。久病必瘀——病程超过5年建议合用桂枝茯苓丸。',opts:[
  {text:'浮肿+尿少+怕冷心悸（糖尿病肾病）',icon:'🦵',next:'zhenwu_tnb'},
  {text:'口渴+尿多+浮肿+小便不利',icon:'💧',next:'wulingsan_dm'},
  {text:'四肢麻木+疼痛+感觉减退（周围神经病变）',icon:'🖐️',next:'huangqiguizhi'},
  {text:'眼底病变+肢体疼痛+舌暗瘀斑（血管并发症）',icon:'👁️',next:'guizhi_dm'}
]},
zhenwu_tnb:{syndrome:'少阴病 · 真武汤（糖尿病肾病/阳虚水泛）',symptoms:'糖尿病多年、浮肿、蛋白尿、怕冷、心悸、小便不利',formula:'炮附子9g(先煎1h) 茯苓9g 芍药9g 白术9g 生姜9g',method:'先煮附子1小时，加其他药煮30分钟。',warning:'⚠️ 需肾内科医生指导。糖尿病肾病需综合管理。不可自行用药。'},
wulingsan_dm:{syndrome:'太阳/太阴 · 五苓散（膀胱气化不利/早期肾病）',symptoms:'口渴+尿多+浮肿+小便不利',formula:'猪苓9g 泽泻15g 白术9g 茯苓9g 桂枝6g',method:'加水800ml煮剩300ml。',otc:'五苓散片',warning:'⚠️ 需医生指导。'},
huangqiguizhi:{syndrome:'血痹 · 黄芪桂枝五物汤（糖尿病周围神经病变）',symptoms:'糖尿病多年、四肢麻木、疼痛、感觉减退、肌肤不仁',original:'《金匮要略》："血痹阴阳俱微……黄芪桂枝五物汤主之。"',formula:'黄芪15g 桂枝9g 芍药9g 生姜18g 大枣12枚',method:'加水800ml煮剩300ml。',warning:'⚠️ 需医生指导。不可自行停药。',hulao:'胡老说：糖尿病四肢麻木是"血痹"——微循环障碍。黄芪桂枝五物汤益气通阳活血。'},
guizhi_dm:{syndrome:'太阳/厥阴 · 桂枝茯苓丸（糖尿病血管并发症/久病化瘀）',symptoms:'糖尿病多年、肢体疼痛麻木、眼底病变、舌暗瘀斑、刺痛固定',formula:'桂枝9g 茯苓9g 丹皮9g 桃仁9g 芍药9g',method:'加水700ml煮剩300ml。',otc:'桂枝茯苓丸',warning:'⚠️ 需医生指导。久病必瘀——病程超5年建议合用。不可自行停药。',hulao:'胡老说：糖尿病后期几乎所有患者都有瘀血——血管被高血糖泡了多年，内膜受损→血小板聚集→微血栓。桂枝茯苓丸是糖尿病后期预防并发症的关键方。'}
}};

