sinisgb:{syndrome:'少阳病 · 四逆散（气滞胆胀）',symptoms:'右上腹胀、打嗝放屁多、情绪波动加重',formula:'柴胡9g 枳实9g 芍药9g 炙甘草6g',method:'加水700ml煮剩300ml。',otc:'逍遥丸 / 舒肝和胃丸',combo:'逍遥丸+低脂饮食。情绪是胆病重要诱因。'},
