uric_only:{syndrome:'尿酸高未发作 · 先做生活方式和复查管理',symptoms:'体检尿酸高，但暂时没有关节红肿热痛',formula:'不按单一经方处理。重点是复查尿酸、肾功能、尿常规，控制酒精、含糖饮料、内脏海鲜浓汤，减重但避免快速节食。',method:'记录尿酸数值、发作次数、肾结石史和用药史，带给医生评估是否需要降尿酸药。',warning:'⚠️ 无症状高尿酸不等于可以自行吃止痛药或长期乱用清热药。若有肾结石、肾功能异常、反复痛风，应正规就诊。'},
joint_emergency:{syndrome:'关节急症风险 · 先排除感染和骨关节损伤',symptoms:'关节剧烈红肿热痛，伴发热寒战、皮肤破溃、糖尿病足风险，或外伤后不能负重',formula:'先去医院骨科/风湿免疫科/急诊。',method:'可能需要血常规、CRP、尿酸、关节超声或关节液检查。',warning:'⚠️ 感染性关节炎会毁关节，不能当普通痛风拖。'}
