thyroid_zhenwu:{syndrome:'少阴病 · 真武汤方向（阳虚水泛）',symptoms:'怕冷、浮肿、小便不利、心慌、头晕、舌淡胖苔白滑',formula:'炮附子9g（先煎1小时） 茯苓9g 芍药9g 白术9g 生姜9g',method:'先煎附子1小时去毒，再加其他药煮30分钟。',warning:'⚠️ 浮肿明显、尿少、胸闷气短需检查心肾功能。附子必须先煎，需医师指导。'}
