maimen_sym:{syndrome:'阳明病虚热 · 麦门冬汤证（肺胃阴虚）',symptoms:'咽喉干燥不利、干咳少痰、口干、舌红少苔、可能声音嘶哑',original:'《金匮要略》："大逆上气，咽喉不利，止逆下气者，麦门冬汤主之。"',formula:'麦冬35g 半夏6g 人参6g 炙甘草6g 粳米15g 大枣4枚',method:'加水1200ml煮到米熟汤成。分三次温服。',otc:'养阴清肺丸 / 麦味地黄丸'},
throat_warn:{syndrome:'咽喉急症风险 · 先排感染和梗阻',symptoms:'高热、咽痛明显、吞咽困难、扁桃体脓点、呼吸不畅',formula:'不建议仅靠工具处理。',method:'及时就医，必要时查血常规、咽拭子或耳鼻喉检查。',warning:'⚠️ 呼吸困难、吞咽困难、高热不退、儿童精神差，需立即就医。'},
sym_daochi:{syndrome:'心经热证 · 导赤散方向',symptoms:'小便黄赤、舌尖痛或舌尖口疮、心烦、口渴',formula:'生地15g 木通6g 竹叶9g 甘草梢6g',method:'加水500ml煮剩200ml。分两次温服。',otc:'导赤丸'},
wuling_sym:{syndrome:'太阳太阴 · 五苓散方向（水液不化）',symptoms:'口渴想喝水、小便不利、浮肿、头晕、可能吐水',formula:'猪苓9g 泽泻15g 白术9g 茯苓9g 桂枝6g',method:'加水800ml煮剩300ml。',otc:'五苓散片',warning:'浮肿明显或尿量明显减少需排查肾功能。'},
sym_banxiabaizhu:{syndrome:'太阴病 · 半夏白术天麻汤方向（痰湿头晕）',symptoms:'头重如裹、眩晕、痰多、胸闷恶心、舌苔厚腻',formula:'半夏9g 白术9g 天麻6g 茯苓9g 橘红6g 甘草3g 生姜3片 大枣3枚',method:'加水800ml煮剩300ml。',otc:'半夏天麻丸'},
sym_ganmai:{syndrome:'太阴病 · 甘麦大枣汤证（脏躁）',symptoms:'情绪低落、想哭、控制不住、呵欠频作、睡前容易悲伤',original:'《金匮要略》："妇人脏躁，喜悲伤欲哭……甘麦大枣汤主之。"',formula:'浮小麦30g 甘草10g 大枣10枚',method:'加水600ml煮剩300ml。可当水温服。'},
