// 统一导出函数
// ===================================================================
function getTree(id) {
  var tree = TREES[id];
  if (!tree) return null;
  for (var key in SHARED) {
    if (!(key in tree.nodes)) {
      tree.nodes[key] = SHARED[key];
    }
  }
  return tree;
}
